public void testRemoveAdvanced() {
	// Remove leaf from complex tree.
	BinarySearchTree<Integer> b = new BinarySearchTree<Integer>();
	b.insert(10);
	b.insert(15);
	b.insert(5);
	b.insert(2);
	b.insert(7);
	b.insert(1);
	b.insert(3);
